			/**
			 * 게시글 상세 화면 데이터 전달 및 화면 구성정보 전달
			 ** @param {"CREATE" | "READ"} psType 게시글 상세 조회 타입
			 */
			function setDtlType(psType) {
			    var vcEmbDtl = app.lookup("embDtl");
			    var voDsBoardList = app.lookup("dsBoardList");
			    var voDmDtlParam = app.lookup("dmDtlParam");
			//    var voRplyParam = app.lookup("dmRplyParam");
			    
			    if (psType == "CREATE") { // 신규
			        var voUserNm = util.Auth.getUserInfo(app, "USER_NM");
			        voDmDtlParam.setValue("WRTR_NM_ENCPT", voUserNm);
			        voDmDtlParam.setValue("FRST_REG_DT", util.DataMap.getValue(app, "dmTime", "strToday"));
			//        voDmDtlParam.setValue("FRST_REG_DT", util.DataMap.getValue(app, "dmTime", "loginNm"));
			        voDmDtlParam.setValue("BRTH_YMD", util.DataMap.getValue(app, "dmTime", "loginBir"));
			        voDmDtlParam.setValue("SXDC_SE_CD", util.DataMap.getValue(app, "dmTime", "loginGen"));
			        voDmDtlParam.setValue("CNTN_IP_ADDR", util.DataMap.getValue(app, "dmTime", "loginIp"));
			        voDmDtlParam.setValue("EML_ADDR_ENCPT", util.DataMap.getValue(app, "dmTime", "loginEmail"));
			        
			        app.lookup("BBSCTT_TTL_NM").focus();  // 커서 위치
			        
			    }else if (psType == "READ") {   
			        var vnRowIdx = util.Grid.getIndex(app, "grdBoardList");
			        voDmDtlParam.setValue("BBSCTT_ESNTAL_NO", voDsBoardList.getValue(vnRowIdx, "BBSCTT_ESNTAL_NO"));
			        voDmDtlParam.setValue("BBSCTT_TYPE_SE_CD", voDsBoardList.getValue(vnRowIdx, "BBSCTT_TYPE_SE_CD"));
			        console.log("vnRowIdx::"+vnRowIdx);
			    }
			    // 상세화면의 함수를 호출하여 데이터 전달
			    vcEmbDtl.ready(function() {
			        var voEmbApp = vcEmbDtl.getEmbeddedAppInstance();
			        if (voEmbApp.hasAppMethod("setDtlData")) {
			            voEmbApp.callAppMethod("setDtlData", psType, voDmDtlParam.getDatas());
			        }
			    });
			    
			    // 게시판 작성 탭 이동
			    selectMdiItem(2);
			}

